## 5️⃣ State Management (Redux Toolkit)

```ts
// src/store/cartSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface CartItem {
  id: string;
  title: string;
  price: number;
  quantity: number;
  image: string;
}

interface CartState {
  items: CartItem[];
}

const initialState: CartState = { items: [] };

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addToCart(state, action: PayloadAction<CartItem>) {
      const existing = state.items.find(i => i.id === action.payload.id);
      if (existing) {
        existing.quantity += 1;
      } else {
        state.items.push({ ...action.payload, quantity: 1 });
      }
    },
    removeFromCart(state, action: PayloadAction<string>) {
      state.items = state.items.filter(i => i.id !== action.payload);
    },
    clearCart(state) {
      state.items = [];
    },
  },
});

export const { addToCart, removeFromCart, clearCart } = cartSlice.actions;
export const selectCartItems = (state: RootState) => state.cart.items;
export const selectCartCount = (state: RootState) =>
  state.cart.items.reduce((sum, item) => sum + item.quantity, 0);

export default cartSlice.reducer;
```

---

## 6️⃣ API Integration

```ts
// src/lib/api.ts
import axios from 'axios';

const api = axios.create({
  baseURL: process.env.NEXT_PUBLIC_API_URL,
  headers: { 'Content-Type': 'application/json' },
});

export const fetchProducts = () => api.get('/products').then(r => r.data);
export const fetchProductBySlug = slug => api.get(`/products/${slug}`).then(r => r.data);
export const createOrder = order => api.post('/orders', order).then(r => r.data);
```

> **Tip:** Use `getStaticProps` + `getStaticPaths` for product pages:

```tsx
export async function getStaticProps({ params }) {
  const product = await fetchProductBySlug(params.slug);
  return { props: { product }, revalidate: 60 }; // ISR
}
```

