## 7️⃣ Testing Strategy

| Test type | Tool | Focus |
|-----------|------|-------|
| Unit | Jest + React Testing Library | Component logic, Redux slices |
| Integration | Cypress | End‑to‑end flows (login, checkout) |
| Visual | Percy / Chromatic | UI regressions |
| Accessibility | axe-core | WCAG compliance |

**Example unit test**

```tsx
// __tests__/components/pages/ProductCard.test.tsx
import { render, screen, fireEvent } from '@testing-library/react';
import { Provider } from 'react-redux';
import configureStore from 'redux-mock-store';
import ProductCard from '@/components/pages/ProductCard';

const mockStore = configureStore([]);

test('renders product info and handles add to cart', () => {
  const store = mockStore({});
  const product = { id: '1', title: 'Test', price: 9.99, image: '/img.png', slug: 'test' };
  render(
    <Provider store={store}>
      <ProductCard product={product} />
    </Provider>
  );

  expect(screen.getByText('Test')).toBeInTheDocument();
  fireEvent.click(screen.getByText(/Add to Cart/i));
  const actions = store.getActions();
  expect(actions[0]).toEqual({ type: 'cart/addToCart', payload: product });
});
```

